75	static inline volatile uint32_t *bk7258_cpu2_control(void)
76	{
77	  return (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
78	}
79	
80	static void bk7258_cpu2_hold_reset(
81	  volatile struct bk7258_cpu2_probe_state_s *state)
82	{
83	  volatile uint32_t *control = bk7258_cpu2_control();
84	  uint32_t value = *control;
85	
86	  value &= ~BK7258_SYS_CPU2_RESET;
87	  *control = value;
88	  __asm volatile ("dsb sy; isb sy" ::: "memory");
89	
90	  if (state != NULL)
91	    {
92	      state->control_after = value;
93	      __asm volatile ("dmb sy" ::: "memory");
94	    }
95	}
96	
97	static int bk7258_cpu2_wait(uint32_t wanted, uint32_t timeout_ms)
98	{
99	  volatile struct bk7258_cpu2_probe_state_s *state =
100	    bk7258_cpu2_probe_state();
101	  uint32_t current;
102	  uint32_t elapsed;
103	
104	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
105	    {
106	      current = state->state;
107	      __asm volatile ("dmb sy" ::: "memory");
108	      if (current == wanted)
109	        {
110	          return OK;
111	        }
112	
113	      if (current == BK7258_CPU2_PROBE_STATE_FAILED)
114	        {
115	          return -EIO;
116	        }
117	
118	      up_mdelay(1);
119	    }
120	
121	  return -ETIMEDOUT;
122	}
123	
124	static void bk7258_cpu2_fail(uint32_t error)
125	{
126	  volatile struct bk7258_cpu2_probe_state_s *state =
127	    bk7258_cpu2_probe_state();
128	
129	  state->secondary_ready = 0;
130	  state->error = error;
131	  __asm volatile ("dmb sy" ::: "memory");
132	  state->state = BK7258_CPU2_PROBE_STATE_FAILED;
133	  __asm volatile ("dmb sy" ::: "memory");
134	}
