136	static void bk7258_cpu2_note_missing_ipi(void)
137	{
138	  volatile struct bk7258_cpu2_probe_state_s *state =
139	    bk7258_cpu2_probe_state();
140	
141	  if (state->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
142	      state->version == BK7258_CPU2_PROBE_STATE_VERSION)
143	    {
144	      state->smp_call_requests++;
145	      if (state->error == BK7258_CPU2_PROBE_ERROR_NONE)
146	        {
147	          state->error = BK7258_CPU2_PROBE_ERROR_IPI_UNAVAILABLE;
148	        }
149	
150	      __asm volatile ("dmb sy; sev" ::: "memory");
151	    }
152	}
