154	static void __attribute__((noinline, noreturn, used))
155	bk7258_ap_secondary_bootstrap(void)
156	{
157	  volatile struct bk7258_cpu2_probe_state_s *state =
158	    bk7258_cpu2_probe_state();
159	  uint32_t control;
160	  uint32_t msp;
161	
162	  __asm volatile ("mrs %0, msp" : "=r" (msp));
163	  __asm volatile ("mrs %0, control" : "=r" (control));
164	
165	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
166	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
167	  state->runtime_vtor = BK7258_SCB_VTOR;
168	  state->runtime_msp = msp;
169	  state->control = control;
170	  state->boot_count++;
171	  __asm volatile ("dmb sy" ::: "memory");
172	
173	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
174	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
175	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
176	    {
177	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
178	      goto parked;
179	    }
180	
181	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
182	  __asm volatile ("dmb sy" ::: "memory");
183	
184	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
185	        BK7258_CPU2_LOCAL_CORE_ID ||
186	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
187	    {
188	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
189	      goto parked;
190	    }
191	
192	  if (state->runtime_vtor !=
193	      (uint32_t)(uintptr_t)__vector_core1_table)
194	    {
195	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
196	      goto parked;
197	    }
198	
199	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
200	      msp > BK7258_CPU2_BOOT_STACK_TOP)
201	    {
202	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
203	      goto parked;
204	    }
205	
206	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
207	      state->idle_stack_base >= state->idle_stack_top ||
208	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
209	    {
210	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
211	      goto parked;
212	    }
213	
214	#ifdef CONFIG_BK7258_AP_IPI
215	  if (bk7258_ap_ipi_secondary_initialize() < 0)
216	    {
217	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
218	      goto parked;
219	    }
220	#endif
221	
222	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
223	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
224	  state->online_mask = BK7258_AP_PRIMARY_MASK;
225	  state->secondary_ready = 1;
226	  __asm volatile ("dmb sy" ::: "memory");
227	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
228	  __asm volatile ("dmb sy; sev" ::: "memory");
229	
230	#ifdef CONFIG_BK7258_AP_IPI
231	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
232	#endif
233	
234	  for (; ; )
235	    {
236	      __asm volatile ("dmb sy" ::: "memory");
237	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
238	        {
239	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
240	          state->secondary_ready = 0;
241	          __asm volatile ("dmb sy" ::: "memory");
242	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
243	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
244	          __asm volatile ("dmb sy; sev" ::: "memory");
245	          goto parked;
246	        }
247	
248	      state->heartbeat++;
249	#ifdef CONFIG_BK7258_AP_IPI
250	      __asm volatile ("dmb sy; dsb sy; wfi" ::: "memory");
251	#else
252	      __asm volatile ("dmb sy; wfe" ::: "memory");
253	#endif
254	    }
255	
256	parked:
257	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
258	  for (; ; )
259	    {
260	      __asm volatile ("wfe");
261	    }
262	}
