264	static void __attribute__((naked, noreturn, used))
265	bk7258_ap_secondary_reset(void)
266	{
267	  __asm volatile
268	    (
269	      "cpsid i\n"
270	      "movs r0, #0\n"
271	      "msr control, r0\n"
272	      "msr basepri, r0\n"
273	      "msr faultmask, r0\n"
274	      "ldr r0, =0x20000000\n"
275	      "movs r1, #1\n"
276	      "str r1, [r0]\n"
277	      "ldr r0, =__vector_core1_table\n"
278	      "ldr r1, =0xe000ed08\n"
279	      "str r0, [r1]\n"
280	      "dsb sy\n"
281	      "isb sy\n"
282	      "b bk7258_ap_secondary_bootstrap\n"
283	    );
284	}
