286	static void __attribute__((noinline, noreturn, used))
287	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
288	{
289	  volatile struct bk7258_cpu2_probe_state_s *state =
290	    bk7258_cpu2_probe_state();
291	  uintptr_t frame = (uintptr_t)stack;
292	  uint32_t error;
293	
294	  state->fault_exception = exception;
295	  state->fault_hfsr = BK7258_SCB_HFSR;
296	  state->fault_cfsr = BK7258_SCB_CFSR;
297	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
298	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
299	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
300	
301	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
302	      frame >= BK7258_CPU2_BOOT_STACK_BASE &&
303	      frame <= BK7258_CPU2_BOOT_STACK_TOP -
304	               BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
305	    {
306	      const volatile uint32_t *regs =
307	        (const volatile uint32_t *)frame;
308	
309	      state->fault_lr = regs[5];
310	      state->fault_pc = regs[6];
311	      state->fault_xpsr = regs[7];
312	    }
313	
314	  error = exception == 2u ?
315	    BK7258_CPU2_PROBE_ERROR_NMI :
316	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
317	  bk7258_cpu2_fail(error);
318	
319	  for (; ; )
320	    {
321	      __asm volatile ("wfe");
322	    }
323	}
324	
325	static void __attribute__((naked, noreturn, used))
326	bk7258_ap_secondary_fault_entry(void)
327	{
328	  __asm volatile
329	    (
330	      "tst lr, #4\n"
331	      "ite eq\n"
332	      "mrseq r0, msp\n"
333	      "mrsne r0, psp\n"
334	      "mrs r1, ipsr\n"
335	      "b bk7258_ap_secondary_fault_handler\n"
336	    );
337	}
