343	int up_cpu_index(void)
344	{
345	  uint32_t cpu = *(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR;
346	
347	  return cpu == BK7258_AP_SECONDARY_CPU ?
348	    BK7258_AP_SECONDARY_CPU : BK7258_AP_PRIMARY_CPU;
349	}
350	
351	uintptr_t up_get_intstackbase(int cpu)
352	{
353	  if (cpu == BK7258_AP_SECONDARY_CPU)
354	    {
355	      return BK7258_CPU2_BOOT_STACK_BASE;
356	    }
357	
358	  return (uintptr_t)g_intstackalloc;
359	}
360	
361	int up_cpu_idlestack(int cpu, struct tcb_s *tcb, size_t stack_size)
362	{
363	  int ret;
364	
365	  if (cpu != BK7258_AP_SECONDARY_CPU || tcb == NULL)
366	    {
367	      return -EINVAL;
368	    }
369	
370	  ret = up_create_stack(tcb, stack_size, TCB_FLAG_TTYPE_KERNEL);
371	  if (ret >= 0)
372	    {
373	      tcb->affinity = (cpu_set_t)1u << cpu;
374	    }
375	
376	  return ret;
377	}
