379	int up_cpu_start(int cpu)
380	{
381	  volatile struct bk7258_cpu2_probe_state_s *state =
382	    bk7258_cpu2_probe_state();
383	  volatile uint32_t *control = bk7258_cpu2_control();
384	  struct tcb_s *tcb;
385	  uintptr_t idle_base;
386	  uintptr_t idle_top;
387	  uint32_t generation;
388	  uint32_t value;
389	  int ret;
390	
391	  if (cpu != BK7258_AP_SECONDARY_CPU)
392	    {
393	      return -EINVAL;
394	    }
395	
396	  bk7258_cpu2_hold_reset(state);
397	  up_mdelay(1);
398	
399	  generation = bk7258_ap_boot_state()->generation;
400	  if (generation == 0)
401	    {
402	      generation = 1;
403	    }
404	
405	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
406	  state->version = BK7258_CPU2_PROBE_STATE_VERSION;
407	  state->size = sizeof(*state);
408	  state->generation = generation;
409	  state->command = BK7258_CPU2_PROBE_COMMAND_START;
410	  state->state = BK7258_CPU2_PROBE_STATE_STARTING;
411	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
412	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
413	  state->vector = (uint32_t)(uintptr_t)__vector_core1_table;
414	  state->initial_msp = BK7258_CPU2_BOOT_STACK_TOP;
415	  state->secondary_entry =
416	    (uint32_t)(uintptr_t)bk7258_ap_secondary_bootstrap;
417	  state->online_mask = BK7258_AP_PRIMARY_MASK;
418	
419	  tcb = current_task(cpu);
420	  if (tcb == NULL || tcb->stack_base_ptr == NULL ||
421	      tcb->adj_stack_size == 0)
422	    {
423	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
424	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
425	      return -ENOMEM;
426	    }
427	
428	  idle_base = (uintptr_t)tcb->stack_base_ptr;
429	  idle_top = idle_base + tcb->adj_stack_size;
430	  state->idle_stack_base = (uint32_t)idle_base;
431	  state->idle_stack_top = (uint32_t)idle_top;
432	
433	  if (idle_base < BK7258_AP_RAM_BASE || idle_base >= idle_top ||
434	      idle_top > BK7258_CPU2_BOOT_STACK_BASE)
435	    {
436	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
437	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
438	      return -ENOMEM;
439	    }
440	
441	  value = *control;
442	  state->control_before = value;
443	  value &= ~(BK7258_SYS_CPU2_RESET |
444	             BK7258_SYS_CPU2_POWER_DOWN |
445	             BK7258_SYS_CPU2_HALT |
446	             BK7258_SYS_CPU2_RXEVT_SEL |
447	             BK7258_SYS_CPU2_BOOT_MASK);
448	  value |= BK7258_SYS_CPU2_RXEVT_SEL;
449	  value |= state->vector & BK7258_SYS_CPU2_BOOT_MASK;
450	  *control = value;
451	  __asm volatile ("dsb sy; isb sy" ::: "memory");
452	
453	  state->control_after = value;
454	  __asm volatile ("dmb sy" ::: "memory");
455	  state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
456	  __asm volatile ("dmb sy" ::: "memory");
457	
458	#ifdef CONFIG_BK7258_AP_IPI
459	  ret = bk7258_ap_ipi_primary_initialize();
460	  if (ret < 0)
461	    {
462	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
463	      return ret;
464	    }
465	#endif
466	
467	  value |= BK7258_SYS_CPU2_RESET;
468	  *control = value;
469	  state->control_after = value;
470	  __asm volatile ("dsb sy; sev" ::: "memory");
471	
472	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SECONDARY_READY,
473	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
474	  if (ret < 0)
475	    {
476	      bk7258_cpu2_hold_reset(state);
477	      if (state->state != BK7258_CPU2_PROBE_STATE_FAILED)
478	        {
479	          bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_TIMEOUT);
480	        }
481	    }
482	
483	  return ret;
484	}
485	
486	int up_send_smp_sched(int cpu)
487	{
488	  if (cpu == up_cpu_index())
489	    {
490	      return OK;
491	    }
492	
493	  if (cpu != BK7258_AP_SECONDARY_CPU)
494	    {
495	      return -EINVAL;
496	    }
497	
498	  bk7258_cpu2_note_missing_ipi();
499	  return -ENOSYS;
500	}
501	
502	void up_send_smp_call(cpu_set_t cpuset)
503	{
504	  int cpu;
505	  int self = up_cpu_index();
506	
507	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
508	    {
509	      if ((cpuset & ((cpu_set_t)1u << cpu)) != 0 && cpu != self)
510	        {
511	          (void)up_send_smp_sched(cpu);
512	        }
513	    }
514	}
515	
516	int bk7258_ap_smp_secondary_stop(uint32_t timeout_ms)
517	{
518	  volatile struct bk7258_cpu2_probe_state_s *state =
519	    bk7258_cpu2_probe_state();
520	  int ret = OK;
521	
522	  if (timeout_ms == 0)
523	    {
524	      timeout_ms = BK7258_CPU2_PROBE_STOP_TIMEOUT_MS;
525	    }
526	
527	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
528	      state->version != BK7258_CPU2_PROBE_STATE_VERSION)
529	    {
530	      ret = -EIO;
531	    }
532	  else if (state->state == BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
533	           state->state == BK7258_CPU2_PROBE_STATE_BOOTSTRAP ||
534	           state->state == BK7258_CPU2_PROBE_STATE_STARTING)
535	    {
536	      state->command = BK7258_CPU2_PROBE_COMMAND_STOP;
537	      __asm volatile ("dmb sy" ::: "memory");
538	#ifdef CONFIG_BK7258_AP_IPI
539	      ret = bk7258_ap_ipi_wake_secondary();
540	      if (ret >= 0)
541	        {
542	          ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
543	                                 timeout_ms);
544	        }
545	#else
546	      __asm volatile ("sev" ::: "memory");
547	      ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
548	                             timeout_ms);
549	#endif
550	    }
551	  else if (state->state == BK7258_CPU2_PROBE_STATE_FAILED)
552	    {
553	      ret = -EIO;
554	    }
555	
556	  bk7258_cpu2_hold_reset(state);
557	  state->secondary_ready = 0;
558	  __asm volatile ("dmb sy" ::: "memory");
559	
560	#ifdef CONFIG_BK7258_AP_IPI
561	  if (ret >= 0)
562	    {
563	      bk7258_ap_ipi_mark_stopped();
564	    }
565	#endif
566	
567	  if (ret < 0 && state->state != BK7258_CPU2_PROBE_STATE_FAILED)
568	    {
569	      bk7258_cpu2_fail(ret == -ETIMEDOUT ?
570	        BK7258_CPU2_PROBE_ERROR_TIMEOUT :
571	        BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
572	    }
573	
574	  return ret;
575	}
