163	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
164	{
165	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
166	  uint32_t elapsed;
167	  uint32_t event;
168	
169	  if (timeout_ms == 0)
170	    {
171	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
172	    }
173	
174	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
175	    {
176	      event = bk7258_ap_mbox_receive();
177	      if (event != BK7258_AP_EVENT_NONE)
178	        {
179	          state->last_event = event;
180	        }
181	
182	      __asm volatile ("dmb sy" ::: "memory");
183	      if (state->state == wanted)
184	        {
185	          return OK;
186	        }
187	
188	      if (state->state == BK7258_AP_STATE_FAILED)
189	        {
190	          return -EIO;
191	        }
192	
193	      nxsig_usleep(1000);
194	    }
195	
196	  return -ETIMEDOUT;
197	}
