202	  int ret;
203	
204	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
205	      (state->state == BK7258_AP_STATE_READY ||
206	       state->state == BK7258_AP_STATE_STARTING))
207	    {
208	      return -EBUSY;
209	    }
