211	  /* Hold CPU1 while replacing shared state and the boot address. */
212	
213	  sys_drv_set_cpu1_reset(0);
214	  __asm volatile ("dsb sy; isb sy" ::: "memory");
215	  bk7258_cpu2_force_reset();
216	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
217	  bk7258_ap_mbox_initialize();
218	  bk7258_ap_state_prepare();
219	
220	  /* Exact BK7258 CPU1 release order from the CP SDK. */
221	
222	  sys_drv_set_cpu1_pwr_dw(0);
223	  sys_drv_set_cpu1_rxevt_sel(1);
224	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
225	  __asm volatile ("dsb sy; isb sy" ::: "memory");
226	  sys_drv_set_cpu1_reset(1);
227	  __asm volatile ("dsb sy; sev" ::: "memory");
228	
229	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
230	  if (ret < 0)
231	    {
232	      sys_drv_set_cpu1_reset(0);
233	      __asm volatile ("dsb sy; isb sy" ::: "memory");
234	      bk7258_cpu2_force_reset();
235	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
236	      sys_drv_set_cpu1_pwr_dw(1);
237	
238	      if (state->state != BK7258_AP_STATE_FAILED)
239	        {
240	          state->error = BK7258_AP_ERROR_TIMEOUT;
241	        }
242	
243	      state->command = BK7258_AP_COMMAND_NONE;
244	      state->state = BK7258_AP_STATE_FAILED;
245	      state->last_event = BK7258_AP_EVENT_FAILED;
246	      __asm volatile ("dmb sy" ::: "memory");
247	    }
248	
249	  return ret;
250	}
