252	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
253	{
254	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
255	  int ret = OK;
256	
257	  if (state->state == BK7258_AP_STATE_READY ||
258	      state->state == BK7258_AP_STATE_STARTING)
259	    {
260	      state->command = BK7258_AP_COMMAND_STOP;
261	      __asm volatile ("dmb sy" ::: "memory");
