367	int bk7258_ap_ipi_test(uint32_t count, uint32_t timeout_ms)
368	{
369	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
370	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
371	  uint32_t elapsed;
372	  uint32_t event;
373	  int ret;
374	
375	  if (count == 0)
376	    {
377	      count = BK7258_AP_IPI_DEFAULT_COUNT;
378	    }
379	
380	  if (timeout_ms == 0)
381	    {
382	      timeout_ms = BK7258_AP_IPI_DEFAULT_TIMEOUT_MS;
383	    }
384	
385	  if (count > BK7258_AP_IPI_MAX_COUNT)
386	    {
387	      return -ERANGE;
388	    }
389	
390	  ret = nxmutex_lock(&g_bk7258_ap_lock);
391	  if (ret < 0)
392	    {
393	      return ret;
394	    }
395	
396	  __asm volatile ("dmb sy" ::: "memory");
397	  if (state->state != BK7258_AP_STATE_READY ||
398	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
399	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
400	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
401	      ipi->generation != state->generation)
402	    {
403	      ret = -EAGAIN;
404	      goto out;
405	    }
406	
407	  if (ipi->state == BK7258_AP_IPI_STATE_RUNNING ||
408	      ipi->state == BK7258_AP_IPI_STATE_REQUESTED)
409	    {
410	      ret = -EBUSY;
411	      goto out;
412	    }
413	
414	  ipi->requested_count = count;
415	  ipi->completed_count = 0;
416	  ipi->timeout_ms = timeout_ms;
417	  ipi->error = BK7258_AP_IPI_ERROR_NONE;
418	  ipi->state = BK7258_AP_IPI_STATE_REQUESTED;
419	  state->command = BK7258_AP_COMMAND_IPI_TEST;
420	  __asm volatile ("dmb sy" ::: "memory");
421	  bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST);
422	
423	  ret = -ETIMEDOUT;
424	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
425	    {
426	      event = bk7258_ap_mbox_receive();
427	      if (event != BK7258_AP_EVENT_NONE)
428	        {
429	          state->last_event = event;
430	        }
431	
432	      __asm volatile ("dmb sy" ::: "memory");
433	      if (ipi->state == BK7258_AP_IPI_STATE_PASSED)
434	        {
435	          ret = OK;
436	          break;
437	        }
438	
439	      if (ipi->state == BK7258_AP_IPI_STATE_FAILED ||
440	          state->state == BK7258_AP_STATE_FAILED)
441	        {
442	          ret = -EIO;
443	          break;
444	        }
445	
446	      nxsig_usleep(1000);
447	    }
448	
449	out:
450	  nxmutex_unlock(&g_bk7258_ap_lock);
451	  return ret;
452	}
