93	  uint32_t generation = bk7258_ap_boot_state()->generation;
94	
95	  return (BK7258_AP_IPI_COMMAND_MAGIC <<
96	          BK7258_AP_IPI_COMMAND_MAGIC_SHIFT) |
97	         ((type & BK7258_AP_IPI_COMMAND_TYPE_MASK) <<
