108	  mailbox_data_t data;
109	  mailbox_endpoint_t src;
110	  mailbox_endpoint_t dst;
111	  int direction = -1;
112	  int self = up_cpu_index();
113	  bk_err_t ret;
114	
115	  if (!bk7258_ap_ipi_state_valid(state))
116	    {
117	      return -EIO;
118	    }
119	
120	  if (self == BK7258_AP_IPI_PRIMARY_CPU &&
121	      target_cpu == BK7258_AP_IPI_SECONDARY_CPU)
122	    {
123	      src = BK7258_AP_IPI_PRIMARY_ENDPOINT;
124	      dst = BK7258_AP_IPI_SECONDARY_ENDPOINT;
125	      if (type == BK7258_AP_IPI_COMMAND_PING)
126	        {
