131	           target_cpu == BK7258_AP_IPI_PRIMARY_CPU)
132	    {
133	      src = BK7258_AP_IPI_SECONDARY_ENDPOINT;
134	      dst = BK7258_AP_IPI_PRIMARY_ENDPOINT;
135	      if (type == BK7258_AP_IPI_COMMAND_PONG)
136	        {
137	          direction = BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY;
138	        }
139	    }
