172	static int bk7258_ap_ipi_record_receive(int direction, uint32_t sequence)
173	{
174	  volatile struct bk7258_ap_ipi_state_s *state = bk7258_ap_ipi_state();
175	  uint32_t expected = state->last_rx_sequence[direction] + 1u;
176	
177	  state->rx_count[direction]++;
178	
179	  if (sequence < expected)
180	    {
181	      state->duplicate_count[direction]++;
182	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_DUPLICATE);
183	      return -EIO;
184	    }
185	
186	  if (sequence > expected)
187	    {
188	      state->lost_count[direction] += sequence - expected;
189	      state->last_rx_sequence[direction] = sequence;
190	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_LOST);
191	      return -EIO;
192	    }
193	
194	  state->last_rx_sequence[direction] = sequence;
195	  __asm volatile ("dmb sy" ::: "memory");
196	  return OK;
197	}
