243	int bk7258_ap_ipi_primary_initialize(void)
244	{
245	  volatile struct bk7258_ap_ipi_state_s *state = bk7258_ap_ipi_state();
246	  uint32_t generation = bk7258_ap_boot_state()->generation;
247	  bk_err_t ret;
248	
249	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
250	  state->version = BK7258_AP_IPI_STATE_VERSION;
251	  state->size = sizeof(*state);
252	  state->generation = generation;
253	  state->state = BK7258_AP_IPI_STATE_INITIALIZING;
254	  __asm volatile ("dmb sy" ::: "memory");
255	  state->magic = BK7258_AP_IPI_STATE_MAGIC;
256	  __asm volatile ("dmb sy" ::: "memory");
257	
258	  ret = bk_mailbox_cc_init();
259	  if (ret != BK_OK)
260	    {
261	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_SDK_IRQ);
262	      return -EIO;
263	    }
264	
265	  /* The vendor AP init configures the CPU1/CPU2 endpoints but deliberately
266	   * leaves the device-wide FIFO layout to endpoint CPU0.  The independent AP
267	   * image has no vendor CPU0 mailbox owner, so finish that SDK-owned global
268	   * initialization here before either AP logical CPU sends a message.
269	   */
270	
271	  ret = bk_mailbox_cc_init_on_current_core(MAILBOX_CPU0);
272	  if (ret != BK_OK)
273	    {
274	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_SDK_MAILBOX);
275	      return -EIO;
276	    }
277	
278	  state->error = BK7258_AP_IPI_ERROR_NONE;
279	  __asm volatile ("dmb sy" ::: "memory");
280	  state->state = BK7258_AP_IPI_STATE_READY;
281	  __asm volatile ("dmb sy; sev" ::: "memory");
282	  return OK;
283	}
284	
285	int bk7258_ap_ipi_secondary_initialize(void)
286	{
287	  volatile struct bk7258_ap_ipi_state_s *state = bk7258_ap_ipi_state();
288	  int ret;
289	
290	  if (!bk7258_ap_ipi_state_valid(state) ||
291	      state->state != BK7258_AP_IPI_STATE_READY)
292	    {
293	      return -EIO;
294	    }
295	
296	  ret = up_prioritize_irq(BK7258_IRQ_MAILBOX,
297	                          NVIC_SYSH_PRIORITY_DEFAULT);
298	  if (ret < 0)
299	    {
300	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_SDK_IRQ);
301	      return ret;
302	    }
303	
304	  bk7258_clear_pending_irq(BK7258_IRQ_MAILBOX);
305	  up_enable_irq(BK7258_IRQ_MAILBOX);
306	  __asm volatile ("dsb sy; isb sy" ::: "memory");
307	  return OK;
308	}
309	
310	void crosscore_mb_rx_isr(mailbox_data_t *data)
311	{
312	  volatile struct bk7258_ap_ipi_state_s *state = bk7258_ap_ipi_state();
313	  uint32_t command;
314	  uint32_t generation;
315	  uint32_t sequence;
316	  uint32_t type;
317	  int local_cpu;
318	  int ret;
319	
320	  if (!bk7258_ap_ipi_state_valid(state) || data == NULL)
321	    {
322	      return;
323	    }
324	
325	  local_cpu = up_cpu_index();
326	  if (local_cpu < BK7258_AP_IPI_PRIMARY_CPU ||
327	      local_cpu > BK7258_AP_IPI_SECONDARY_CPU)
328	    {
329	      state->spurious_count++;
330	      return;
331	    }
332	
333	  state->irq_count[local_cpu]++;
334	  state->wake_count[local_cpu]++;
335	  command = data->param2;
336	  state->last_command[local_cpu] = command;
337	
338	  if ((command >> BK7258_AP_IPI_COMMAND_MAGIC_SHIFT) !=
339	      BK7258_AP_IPI_COMMAND_MAGIC)
340	    {
341	      state->spurious_count++;
342	      if (state->state == BK7258_AP_IPI_STATE_RUNNING)
343	        {
344	          bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_BAD_COMMAND);
345	        }
346	
347	      return;
348	    }
349	
350	  generation = (command >> BK7258_AP_IPI_COMMAND_GEN_SHIFT) &
351	               BK7258_AP_IPI_COMMAND_GEN_MASK;
352	  if (generation !=
353	      (state->generation & BK7258_AP_IPI_COMMAND_GEN_MASK))
354	    {
355	      state->stale_count++;
356	      return;
357	    }
358	
359	  type = (command >> BK7258_AP_IPI_COMMAND_TYPE_SHIFT) &
360	         BK7258_AP_IPI_COMMAND_TYPE_MASK;
361	  sequence = command & BK7258_AP_IPI_COMMAND_SEQ_MASK;
362	
363	  if (type == BK7258_AP_IPI_COMMAND_WAKE)
364	    {
365	      if (local_cpu != BK7258_AP_IPI_SECONDARY_CPU ||
366	          data->param0 != BK7258_AP_IPI_PRIMARY_ENDPOINT)
367	        {
368	          state->spurious_count++;
369	        }
370	
371	      return;
372	    }
373	
374	  if (state->state != BK7258_AP_IPI_STATE_RUNNING)
375	    {
376	      state->spurious_count++;
377	      return;
378	    }
379	
380	  if (type == BK7258_AP_IPI_COMMAND_PING)
381	    {
382	      if (local_cpu != BK7258_AP_IPI_SECONDARY_CPU ||
383	          data->param0 != BK7258_AP_IPI_PRIMARY_ENDPOINT ||
384	          data->param1 != BK7258_AP_IPI_SECONDARY_CPU)
385	        {
386	          bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_BAD_ENDPOINT);
387	          return;
388	        }
389	
390	      ret = bk7258_ap_ipi_record_receive(
391	        BK7258_AP_IPI_DIR_PRIMARY_TO_SECONDARY, sequence);
392	      if (ret >= 0)
393	        {
394	          (void)bk7258_ap_ipi_send(BK7258_AP_IPI_COMMAND_PONG,
395	                                   sequence,
396	                                   BK7258_AP_IPI_PRIMARY_CPU);
397	        }
398	
399	      return;
400	    }
401	
402	  if (type == BK7258_AP_IPI_COMMAND_PONG)
403	    {
404	      if (local_cpu != BK7258_AP_IPI_PRIMARY_CPU ||
405	          data->param0 != BK7258_AP_IPI_SECONDARY_ENDPOINT ||
406	          data->param1 != BK7258_AP_IPI_PRIMARY_CPU)
407	        {
408	          bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_BAD_ENDPOINT);
409	          return;
410	        }
411	
412	      (void)bk7258_ap_ipi_record_receive(
413	        BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY, sequence);
414	      return;
415	    }
416	
417	  bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_BAD_COMMAND);
418	}
419	
420	int bk7258_ap_ipi_selftest(uint32_t count, uint32_t timeout_ms)
421	{
422	  volatile struct bk7258_ap_ipi_state_s *state = bk7258_ap_ipi_state();
423	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
424	    bk7258_cpu2_probe_state();
425	  uint32_t elapsed = 0;
426	  uint32_t heartbeat_before;
427	  uint32_t sequence;
428	  int ret;
429	
430	  if (count == 0)
431	    {
432	      count = BK7258_AP_IPI_DEFAULT_COUNT;
433	    }
434	
435	  if (timeout_ms == 0)
436	    {
437	      timeout_ms = BK7258_AP_IPI_DEFAULT_TIMEOUT_MS;
438	    }
439	
440	  if (count > BK7258_AP_IPI_MAX_COUNT)
441	    {
442	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_BAD_COMMAND);
443	      return -ERANGE;
444	    }
445	
446	  if (!bk7258_ap_ipi_state_valid(state) ||
447	      (state->state != BK7258_AP_IPI_STATE_READY &&
448	       state->state != BK7258_AP_IPI_STATE_REQUESTED &&
449	       state->state != BK7258_AP_IPI_STATE_PASSED &&
450	       state->state != BK7258_AP_IPI_STATE_FAILED) ||
451	      cpu2->state != BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
452	      cpu2->secondary_ready != 1 || cpu2->online_mask != 1)
453	    {
454	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_BAD_STATE);
455	      return -EAGAIN;
456	    }
457	
458	  bk7258_ap_ipi_reset_test(state, count, timeout_ms);
459	
460	  for (sequence = 1; sequence <= count; sequence++)
461	    {
462	      heartbeat_before = cpu2->heartbeat;
463	      __asm volatile ("dmb sy" ::: "memory");
464	      ret = bk7258_ap_ipi_send(BK7258_AP_IPI_COMMAND_PING, sequence,
465	                               BK7258_AP_IPI_SECONDARY_CPU);
466	      if (ret < 0)
467	        {
468	          return ret;
469	        }
470	
471	      while (state->last_rx_sequence[
472	             BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY] < sequence)
473	        {
474	          if (state->state == BK7258_AP_IPI_STATE_FAILED)
475	            {
476	              return -EIO;
477	            }
478	
479	          if (elapsed >= timeout_ms)
480	            {
481	              bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_TIMEOUT);
482	              return -ETIMEDOUT;
483	            }
484	
485	          up_mdelay(1);
486	          elapsed++;
487	        }
488	
489	      while (cpu2->heartbeat == heartbeat_before)
490	        {
491	          if (state->state == BK7258_AP_IPI_STATE_FAILED)
492	            {
493	              return -EIO;
494	            }
495	
496	          if (elapsed >= timeout_ms)
497	            {
498	              bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_TIMEOUT);
499	              return -ETIMEDOUT;
500	            }
501	
502	          up_mdelay(1);
503	          elapsed++;
504	        }
505	
506	      state->completed_count = sequence;
507	      __asm volatile ("dmb sy" ::: "memory");
508	    }
509	
510	  if (state->tx_count[BK7258_AP_IPI_DIR_PRIMARY_TO_SECONDARY] !=
511	        count ||
512	      state->rx_count[BK7258_AP_IPI_DIR_PRIMARY_TO_SECONDARY] !=
513	        count ||
514	      state->tx_count[BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY] !=
515	        count ||
516	      state->rx_count[BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY] !=
517	        count ||
518	      state->last_tx_sequence[
519	        BK7258_AP_IPI_DIR_PRIMARY_TO_SECONDARY] != count ||
520	      state->last_rx_sequence[
521	        BK7258_AP_IPI_DIR_PRIMARY_TO_SECONDARY] != count ||
522	      state->last_tx_sequence[
523	        BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY] != count ||
524	      state->last_rx_sequence[
525	        BK7258_AP_IPI_DIR_SECONDARY_TO_PRIMARY] != count ||
526	      state->irq_count[BK7258_AP_IPI_PRIMARY_CPU] != count ||
527	      state->irq_count[BK7258_AP_IPI_SECONDARY_CPU] != count ||
528	      state->wake_count[BK7258_AP_IPI_PRIMARY_CPU] != count ||
529	      state->wake_count[BK7258_AP_IPI_SECONDARY_CPU] != count ||
530	      state->stale_count != 0 || state->spurious_count != 0)
531	    {
532	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_COUNT_MISMATCH);
533	      return -EIO;
534	    }
535	
536	  if (state->duplicate_count[0] != 0 ||
537	      state->duplicate_count[1] != 0)
538	    {
539	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_DUPLICATE);
540	      return -EIO;
541	    }
542	
543	  if (state->lost_count[0] != 0 || state->lost_count[1] != 0)
544	    {
545	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_LOST);
546	      return -EIO;
547	    }
548	
549	  if (state->send_failures[0] != 0 || state->send_failures[1] != 0)
550	    {
551	      bk7258_ap_ipi_fail(BK7258_AP_IPI_ERROR_SEND);
552	      return -EIO;
553	    }
554	
555	  state->error = BK7258_AP_IPI_ERROR_NONE;
556	  __asm volatile ("dmb sy" ::: "memory");
557	  state->state = BK7258_AP_IPI_STATE_PASSED;
558	  __asm volatile ("dmb sy; sev" ::: "memory");
559	  return OK;
560	}
