154	static int bk7258_ap_validate_secondary_bootstrap(void)
155	{
156	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
157	    bk7258_cpu2_probe_state();
158	#ifdef CONFIG_BK7258_AP_IPI
159	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
160	#endif
161	
162	  __asm volatile ("dmb sy" ::: "memory");
163	
164	  if (cpu2->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
165	      cpu2->version != BK7258_CPU2_PROBE_STATE_VERSION ||
166	      cpu2->size != sizeof(struct bk7258_cpu2_probe_state_s) ||
167	      cpu2->generation != bk7258_ap_boot_state()->generation ||
168	      cpu2->state != BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
169	      cpu2->error != BK7258_CPU2_PROBE_ERROR_NONE ||
170	      cpu2->secondary_ready != 1 ||
171	      cpu2->online_mask != 1 ||
172	      cpu2->local_core_id != 1 ||
173	      cpu2->physical_core_id != 2 ||
174	      cpu2->runtime_vtor != cpu2->vector ||
175	      cpu2->runtime_msp <= BK7258_CPU2_BOOT_STACK_BASE ||
176	      cpu2->runtime_msp > BK7258_CPU2_BOOT_STACK_TOP ||
177	      cpu2->idle_stack_base < BK7258_AP_RAM_BASE ||
178	      cpu2->idle_stack_base >= cpu2->idle_stack_top ||
179	      cpu2->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
180	    {
181	      return BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
182	    }
183	
184	#ifdef CONFIG_BK7258_AP_IPI
185	  if (ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
186	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
187	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
188	      ipi->generation != bk7258_ap_boot_state()->generation ||
189	      ipi->state != BK7258_AP_IPI_STATE_READY ||
190	      ipi->error != BK7258_AP_IPI_ERROR_NONE)
191	    {
192	      return BK7258_AP_ERROR_CPU2_IPI;
193	    }
194	#endif
195	
196	  return BK7258_AP_ERROR_NONE;
197	}
