258	{
259	  uint32_t regaddr;
260	  int shift;
261	  DEBUGASSERT(irq >= NVIC_IRQ_MEMFAULT && irq < NR_IRQS &&
262	              priority >= NVIC_SYSH_PRIORITY_MAX &&
263	              priority <= NVIC_SYSH_PRIORITY_MIN);
264	  if (irq < NVIC_IRQ_FIRST)
265	    {
266	      /* NVIC_SYSH_PRIORITY() maps {0..15} to one of three priority
267	       * registers (0-3 are invalid)
268	       */
269	
270	      regaddr = NVIC_SYSH_PRIORITY(irq);
271	      irq    -= NVIC_IRQ_MEMFAULT;
272	    }
273	
274	  else
275	    {
276	      /* NVIC_IRQ_PRIORITY() maps {0..} to one of many priority registers */
277	
278	      irq    -= NVIC_IRQ_FIRST;
279	      regaddr = NVIC_IRQ_PRIORITY(irq);
280	    }
281	
282	  shift = (irq & 3) << 3;
283	  modifyreg32(regaddr, 0xff << shift, priority << shift);
284	  return OK;
285	}
