229	
230	int bk7258_ap_main(int argc, char *argv[])
231	{
232	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
233	  uint32_t event;
234	  int error;
235	  int ret;
236	
237	  (void)argc;
238	  (void)argv;
239	
240	  if (state->magic != BK7258_AP_BOOT_STATE_MAGIC ||
241	      state->version != BK7258_AP_BOOT_STATE_VERSION ||
242	      state->size != sizeof(struct bk7258_ap_boot_state_s))
243	    {
244	      state->state = BK7258_AP_STATE_FAILED;
245	      state->error = BK7258_AP_ERROR_BAD_BOOT_STATE;
246	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
247	      goto parked;
248	    }
249	
250	  error = bk7258_ap_validate_runtime();
251	  if (error != BK7258_AP_ERROR_NONE)
252	    {
253	      state->state = BK7258_AP_STATE_FAILED;
254	      state->error = (uint32_t)error;
255	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
256	      goto parked;
257	    }
258	
259	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
260	  error = bk7258_ap_validate_secondary_bootstrap();
261	  if (error != BK7258_AP_ERROR_NONE)
262	    {
263	      state->state = BK7258_AP_STATE_FAILED;
264	      state->error = (uint32_t)error;
265	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
266	      goto parked;
267	    }
268	#else
269	  ret = bk7258_cpu2_probe_start(BK7258_CPU2_PROBE_TIMEOUT_MS);
270	  if (ret < 0)
271	    {
272	      state->state = BK7258_AP_STATE_FAILED;
273	      state->error = BK7258_AP_ERROR_CPU2_PROBE;
274	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
275	      goto parked;
276	    }
277	#endif
278	
279	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
280	  ret = bk7258_ap_smp_scheduler_selftest(
281	    BK7258_AP_SMP_DEFAULT_TIMEOUT_MS);
282	  if (ret < 0)
283	    {
284	      state->state = BK7258_AP_STATE_FAILED;
285	      state->error = BK7258_AP_ERROR_CPU2_SMP_SCHEDULER;
286	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
287	      goto parked;
288	    }
289	#endif
290	
291	  state->error      = BK7258_AP_ERROR_NONE;
292	  state->last_event = BK7258_AP_EVENT_READY;
293	  state->state      = BK7258_AP_STATE_READY;
294	  __asm volatile ("dmb sy" ::: "memory");
295	  bk7258_ap_mbox_send(BK7258_AP_EVENT_READY);
296	
297	  for (; ; )
298	    {
299	      event = bk7258_ap_mbox_receive();
300	      if (event != BK7258_AP_EVENT_NONE)
301	        {
302	          state->last_event = event;
303	        }
304	
305	      if (event == BK7258_AP_EVENT_STOP ||
306	          state->command == BK7258_AP_COMMAND_STOP)
307	        {
308	          state->state = BK7258_AP_STATE_STOPPING;
309	          __asm volatile ("dmb sy" ::: "memory");
310	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
311	          ret = bk7258_ap_smp_secondary_stop(
312	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
313	#else
314	          ret = bk7258_cpu2_probe_stop(
315	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
316	#endif
317	          if (ret < 0)
318	            {
319	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
320	              state->error = BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
321	#else
322	              state->error = BK7258_AP_ERROR_CPU2_PROBE;
323	#endif
324	              state->state = BK7258_AP_STATE_FAILED;
325	              state->last_event = BK7258_AP_EVENT_FAILED;
326	              bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
327	              break;
328	            }
329	
330	          state->state = BK7258_AP_STATE_STOPPED;
331	          state->last_event = BK7258_AP_EVENT_STOPPED;
332	          bk7258_ap_mbox_send(BK7258_AP_EVENT_STOPPED);
333	          break;
334	        }
335	
336	#ifdef CONFIG_BK7258_AP_IPI
337	      if (event == BK7258_AP_EVENT_IPI_TEST ||
338	          state->command == BK7258_AP_COMMAND_IPI_TEST)
339	        {
340	          volatile struct bk7258_ap_ipi_state_s *ipi =
341	            bk7258_ap_ipi_state();
342	
343	          state->command = BK7258_AP_COMMAND_NONE;
344	          __asm volatile ("dmb sy" ::: "memory");
345	          ret = bk7258_ap_ipi_selftest(ipi->requested_count,
346	                                       ipi->timeout_ms);
347	          if (ret < 0)
348	            {
349	              state->error = BK7258_AP_ERROR_CPU2_IPI;
350	              state->last_event = BK7258_AP_EVENT_IPI_TEST_FAILED;
351	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_FAILED);
352	            }
353	          else
354	            {
355	              state->error = BK7258_AP_ERROR_NONE;
356	              state->last_event = BK7258_AP_EVENT_IPI_TEST_PASSED;
357	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_PASSED);
358	            }
359	        }
360	#endif
361	
362	      state->heartbeat++;
363	      __asm volatile ("dmb sy; sev" ::: "memory");
364	      nxsig_usleep(BK7258_AP_HEARTBEAT_US);
365	    }
366	
367	parked:
368	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
369	  for (; ; )
370	    {
371	      __asm volatile ("wfe");
372	    }
373	
374	  return 0;
375	}
