56	static void bk7258_ap_reset_entry(void)
57	{
58	  /* SMP stack selection calls up_cpu_index() before __start().  Publish the
59	   * AP-local primary ID before arm_initialize_stack() asks for CPU0's
60	   * interrupt stack.  The AP-UP path writes the same value and is unchanged.
61	   */
62	
63	  *(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR = 0;
64	  __asm volatile ("dmb sy" ::: "memory");
65	
66	  /* Follow the common ARM reset wrapper before entering board __start:
67	   * preserve the reset stack as PSP for the IDLE thread, switch MSP to the
68	   * dedicated interrupt stack, and terminate the backtrace chain at LR=0.
69	   */
70	
71	  arm_initialize_stack();
72	
73	  __asm volatile ("mov lr, %0\n\t"
74	                  "bx %1\n\t"
75	                  :
76	                  : "r"(0), "r"(__start));
77	}
