79	static inline void bk7258_ap_fault_doorbell(uint32_t event,
80	                                            uint32_t error)
81	{
82	  volatile uint32_t *mbox =
83	    (volatile uint32_t *)(uintptr_t)BK7258_MBOX1_BASE;
84	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
85	
86	  state->state      = BK7258_AP_STATE_FAILED;
87	  state->error      = error;
88	  state->last_event = event;
89	
90	  mbox[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
91	  mbox[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
92	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
93	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
94	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
95	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->state;
96	  __asm volatile ("dmb sy" ::: "memory");
97	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
98	  __asm volatile ("dsb sy; isb sy" ::: "memory");
99	}
