101	static void __attribute__((noinline, noreturn, used))
102	bk7258_ap_fault_handler(uint32_t *stack, uint32_t exc_return,
103	                        uint32_t exception)
104	{
105	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
106	  volatile struct bk7258_ap_fault_state_s *fault = bk7258_ap_fault_state();
107	  uintptr_t frame_addr = (uintptr_t)stack;
108	  const volatile uint32_t *frame;
109	  uint32_t error;
110	  uint32_t stacked_r0 = BK7258_FAULT_INVALID_VALUE;
111	  uint32_t stacked_r1 = BK7258_FAULT_INVALID_VALUE;
112	  uint32_t stacked_r2 = BK7258_FAULT_INVALID_VALUE;
113	  uint32_t stacked_r3 = BK7258_FAULT_INVALID_VALUE;
114	  uint32_t stacked_r12 = BK7258_FAULT_INVALID_VALUE;
115	  uint32_t stacked_lr = BK7258_FAULT_INVALID_VALUE;
116	  uint32_t stacked_pc = BK7258_FAULT_INVALID_VALUE;
117	  uint32_t stacked_xpsr = BK7258_FAULT_INVALID_VALUE;
118	  uint32_t hfsr = BK7258_SCB_HFSR;
119	  uint32_t cfsr = BK7258_SCB_CFSR;
120	  uint32_t mmfar = BK7258_SCB_MMFAR;
121	  uint32_t bfar = BK7258_SCB_BFAR;
122	
123	  /* Hardware places the basic frame after the optional FP frame. */
124	
125	  if ((exc_return & BK7258_EXC_RETURN_BASIC_FRAME) == 0)
126	    {
127	      frame_addr += BK7258_EXCEPTION_FP_FRAME_WORDS * sizeof(uint32_t);
128	    }
129	
130	  if ((frame_addr & (sizeof(uint32_t) - 1u)) == 0 &&
131	      frame_addr >= BK7258_AP_RAM_BASE &&
132	      frame_addr <= BK7258_SHARED_RAM_BASE -
133	                    BK7258_EXCEPTION_FRAME_WORDS * sizeof(uint32_t))
134	    {
135	      frame = (const volatile uint32_t *)frame_addr;
136	      stacked_r0   = frame[0];
137	      stacked_r1   = frame[1];
138	      stacked_r2   = frame[2];
139	      stacked_r3   = frame[3];
140	      stacked_r12  = frame[4];
141	      stacked_lr   = frame[5];
142	      stacked_pc   = frame[6];
143	      stacked_xpsr = frame[7];
144	    }
145	
146	  if (exception == BK7258_EXCEPTION_NMI)
147	    {
148	      error = BK7258_AP_ERROR_NMI;
149	    }
150	  else if (exception == BK7258_EXCEPTION_HARDFAULT)
151	    {
152	      error = BK7258_AP_ERROR_HARDFAULT;
153	    }
154	  else
155	    {
156	      error = BK7258_AP_ERROR_BAD_BOOT_STATE;
157	    }
158	
159	  /* Preserve the four-word quick dump at 0x2809f070. */
160	
161	  state->reserved[0] = exception;
162	  state->reserved[1] = hfsr;
163	  state->reserved[2] = cfsr;
164	  state->reserved[3] = stacked_pc;
165	
166	  /* Publish the complete record at 0x2809f080.  Magic is written last so a
167	   * debugger never mistakes a partially populated record for a valid one.
168	   */
169	
170	  fault->magic         = 0;
171	  fault->version       = BK7258_AP_FAULT_STATE_VERSION;
172	  fault->size          = sizeof(*fault);
173	  fault->generation    = state->generation;
174	  fault->exception     = exception;
175	  fault->error         = error;
176	  fault->exc_return    = exc_return;
177	  fault->stack_pointer = (uint32_t)(uintptr_t)stack;
178	  fault->hfsr          = hfsr;
179	  fault->cfsr          = cfsr;
180	  fault->mmfar         = mmfar;
181	  fault->bfar          = bfar;
182	  fault->stacked_r0    = stacked_r0;
183	  fault->stacked_r1    = stacked_r1;
184	  fault->stacked_r2    = stacked_r2;
185	  fault->stacked_r3    = stacked_r3;
186	  fault->stacked_r12   = stacked_r12;
187	  fault->stacked_lr    = stacked_lr;
188	  fault->stacked_pc    = stacked_pc;
189	  fault->stacked_xpsr  = stacked_xpsr;
190	  __asm volatile ("dmb sy" ::: "memory");
191	  fault->magic = BK7258_AP_FAULT_STATE_MAGIC;
192	
193	  bk7258_ap_fault_doorbell(BK7258_AP_EVENT_FAILED, error);
194	
195	  for (; ; )
196	    {
197	      __asm volatile ("wfe");
198	    }
199	}
